<?php
namespace App\Services;use App\Models\{AttendanceEvent,AttendanceEvidence};use Barryvdh\DomPDF\Facade\Pdf;use Illuminate\Support\Facades\Storage;class AttendanceEvidenceService{public function generate(AttendanceEvent $event,int $userId):AttendanceEvidence{$event->load(['company','participants.record.signature','attendable']);if($event->attendable instanceof \App\Models\TrainingSession)$event->attendable->loadMissing(['instructorEmployee','externalInstructor']);$version=($event->evidences()->max('version')??0)+1;$signatures=[];foreach($event->records as $record)if($record->signature){$bytes=Storage::disk(config('attendance.disk'))->get($record->signature->file_path);$signatures[$record->id]='data:image/png;base64,'.base64_encode($bytes);}$content=Pdf::loadView('pdf.attendance_evidence',compact('event','signatures'))->output();$path="attendance/evidences/{$event->uuid}/v{$version}.pdf";Storage::disk(config('attendance.disk'))->put($path,$content);$evidence=$event->evidences()->create(['version'=>$version,'file_path'=>$path,'file_hash'=>hash('sha256',$content),'generated_at'=>now(),'generated_by'=>$userId]);app(AttendanceEventService::class)->audit($event,'attendance_evidence_generated',$userId,['evidence_id'=>$evidence->id]);return$evidence;}}
